        public async Task<TrainerProfileDto?> CreateAsync(TrainerCreateDto dto)
        {
            // prevent duplicate trainer for same user
            var exists = await _repository.UserHasTrainerProfileAsync(dto.UserId);
            if (exists) return null;

            var model = new NFD_Trainer
            {
                UserId = dto.UserId,
                Specialty = dto.Specialty,
                ExperienceYears = dto.ExperienceYears,
                Biography = dto.Biography,
                CVUrl = dto.CVUrl,
                Status = NFD_TrainerStatus.Active
            };

            await _repository.AddAsync(model);
            var saved = await _repository.SaveChangesAsync();
            if (!saved) return null;

            // reload with user
            var created = await _repository.GetByIdAsync(model.TrainerId);
            if (created == null) return null;

            return await GetByIdAsync(created.TrainerId);
        }

        public async Task<bool> UpdateAsync(int id, TrainerUpdateDto dto)
        {
            var existing = await _repository.GetByIdAsync(id);

            if (existing == null)
                return false;

            // تحديث بيانات المدرب
            existing.Specialty = dto.Specialty;
            existing.ExperienceYears = dto.ExperienceYears;
            existing.Biography = dto.Biography;
            existing.CVUrl = dto.CVUrl;

            // تحديث بيانات المستخدم المرتبط بالمدرب
            if (existing.User != null)
            {
                if (!string.IsNullOrWhiteSpace(dto.FullName))
                    existing.User.FullName = dto.FullName.Trim();

                if (!string.IsNullOrWhiteSpace(dto.Email))
                    existing.User.Email = dto.Email.Trim();

                existing.User.Phone =
                    string.IsNullOrWhiteSpace(dto.Phone)
                        ? null
                        : dto.Phone.Trim();
            }

            _repository.Update(existing);

            return await _repository.SaveChangesAsync();
        }
        // =====================================================
        // UPLOAD TRAINER PROFILE IMAGE
        // =====================================================

        public async Task<string?> UploadProfileImageAsync(
            int trainerId,
            IFormFile file
        )
        {
            // ---------------------------------------------
            // Find trainer
            // ---------------------------------------------

            var trainer =
                await _repository.GetByIdAsync(
                    trainerId
                );


            if (trainer == null)
            {
                return null;
            }


            // ---------------------------------------------
            // Validate uploaded file
            // ---------------------------------------------

            if (
                file == null ||
                file.Length == 0
            )
            {
                throw new ArgumentException(
                    "Profile image is required."
                );
            }


            // Maximum allowed size: 5 MB
            const long maxFileSize =
                5 * 1024 * 1024;


            if (
                file.Length > maxFileSize
            )
            {
                throw new ArgumentException(
                    "Profile image cannot exceed 5 MB."
                );
            }


            // ---------------------------------------------
            // Validate file extension
            // ---------------------------------------------

            var extension =
                Path.GetExtension(
                    file.FileName
                )
                .ToLowerInvariant();


            var allowedExtensions =
                new HashSet<string>
                {
            ".jpg",
            ".jpeg",
            ".png",
            ".webp"
                };


            if (
                !allowedExtensions.Contains(
                    extension
                )
            )
            {
                throw new ArgumentException(
                    "Only JPG, JPEG, PNG and WEBP images are allowed."
                );
            }


            // ---------------------------------------------
            // Validate content type
            // ---------------------------------------------

            var allowedContentTypes =
                new HashSet<string>
                {
            "image/jpeg",
            "image/png",
            "image/webp"
                };


            if (
                !allowedContentTypes.Contains(
                    file.ContentType.ToLowerInvariant()
                )
            )
            {
                throw new ArgumentException(
                    "Invalid image type."
                );
            }


            // ---------------------------------------------
            // Get physical storage folder
            // ---------------------------------------------

            var storagePath =
                _configuration[
                    "Storage:TrainerProfileImagesPath"
                ];


            if (
                string.IsNullOrWhiteSpace(
                    storagePath
                )
            )
            {
                throw new InvalidOperationException(
                    "Trainer profile image storage path is not configured."
                );
            }


            Directory.CreateDirectory(
                storagePath
            );


            // ---------------------------------------------
            // Get public request path
            // ---------------------------------------------

            var requestPath =
                _configuration[
                    "Storage:TrainerProfileImagesRequestPath"
                ]
                ?? "/uploads/trainer-profiles";


            requestPath =
                requestPath.TrimEnd('/');


            // ---------------------------------------------
            // Generate unique safe filename
            // ---------------------------------------------

            var fileName =
                $"trainer-{trainerId}-{Guid.NewGuid():N}{extension}";


            var fullPath =
                Path.Combine(
                    storagePath,
                    fileName
                );


            // Keep old image URL so we can delete
            // the previous physical image later.
            var oldProfileImageUrl =
                trainer.ProfileImageUrl;


            // ---------------------------------------------
            // Save new image physically
            // ---------------------------------------------

            await using (
                var stream =
                    new FileStream(
                        fullPath,
                        FileMode.CreateNew
                    )
            )
            {
                await file.CopyToAsync(
                    stream
                );
            }


            // ---------------------------------------------
            // Build public URL
            // ---------------------------------------------

            var profileImageUrl =
                $"{requestPath}/{fileName}";


            // ---------------------------------------------
            // Save image URL in database
            // ---------------------------------------------

            trainer.ProfileImageUrl =
                profileImageUrl;


            _repository.Update(
                trainer
            );


            // ---------------------------------------------
            // Save database changes safely
            // ---------------------------------------------

            bool saved;


            try
            {
                saved =
                    await _repository.SaveChangesAsync();
            }
            catch
            {
                // If the database operation fails,
                // remove the newly uploaded physical file
                // to avoid leaving an orphan file.
                if (
                    File.Exists(
                        fullPath
                    )
                )
                {
                    File.Delete(
                        fullPath
                    );
                }


                // Restore the old URL in the tracked entity.
                trainer.ProfileImageUrl =
                    oldProfileImageUrl;


                throw;
            }


            if (!saved)
            {
                // Database did not save the new URL,
                // so remove the newly uploaded file.
                if (
                    File.Exists(
                        fullPath
                    )
                )
                {
                    File.Delete(
                        fullPath
                    );
                }


                trainer.ProfileImageUrl =
                    oldProfileImageUrl;


                throw new InvalidOperationException(
                    "Could not save trainer profile image."
                );
            }

            // ---------------------------------------------
            // Delete previous profile image
            // after the new one was saved successfully.
            // ---------------------------------------------

            if (
                !string.IsNullOrWhiteSpace(
                    oldProfileImageUrl
                )
            )
            {
                var oldFileName =
                    Path.GetFileName(
                        oldProfileImageUrl
                    );


                if (
                    !string.IsNullOrWhiteSpace(
                        oldFileName
                    )
                )
                {
                    var oldFullPath =
                        Path.Combine(
                            storagePath,
                            oldFileName
                        );


                    if (
                        File.Exists(
                            oldFullPath
                        )
                    )
                    {
                        File.Delete(
                            oldFullPath
                        );
                    }
                }
            }


            // Return URL that will also be stored in database.
            return profileImageUrl;
        }

        public async Task<bool> UpdateStatusAsync(int id, TrainerStatusUpdateDto dto)
        {
            var existing = await _repository.GetByIdAsync(id);
            if (existing == null) return false;

            existing.Status = dto.Status;

            _repository.Update(existing);
            return await _repository.SaveChangesAsync();
        }

        public async Task<List<TrainerBatchDto>> GetBatchesAsync(int id)
        {
            var t = await _repository.GetByIdWithBatchesAsync(id);
            if (t == null) return new List<TrainerBatchDto>();

            string[] departments = {
        "تطوير البرمجيات وتقنية المعلومات",
        "الأمن السيبراني والشبكات",
        "الذكاء الاصطناعي وتحليل البيانات",
        "تصميم واجهات وتجربة المستخدم UX/UI"
    };

            return t.BatchTrainers.Select(bt =>
            {
                int seed = bt.Batch.BatchId;
                return new TrainerBatchDto
                {
                    BatchId = bt.Batch.BatchId,
                    BatchName = bt.Batch.BatchName,
                    StartDate = bt.Batch.StartDate,
                    EndDate = bt.Batch.EndDate,
                    Status = bt.Batch.Status,
                    Department = departments[seed % departments.Length],
                    EnrolledTraineesCount = 18 + (seed * 5) % 15,
                    AttendanceRate = 88 + (seed * 3) % 11,
                    ProgressPercentage = 40 + (seed * 13) % 55
                };
            }).ToList();
        }

